import{_ as e,o as t,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"大周天","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-大周天.md","filePath":"50-概念资料/dict-大周天.md","lastUpdated":1778040484000}'),r={name:"50-概念资料/dict-大周天.md"};function i(c,a,d,u,h,n){return t(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="大周天" tabindex="-1">大周天 <a class="header-anchor" href="#大周天" aria-label="Permalink to &quot;大周天&quot;">​</a></h1><blockquote><p>传统：丹道</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>大周天是丹道修炼中比小周天更深入的阶段——真气打通全身经脉，不仅仅是任督二脉，而是包括十二经络等更广泛的循环。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;大周天就是全身的经脉都通了。小周天只是任督，大周天全身的气都循环起来了。&quot;</p></blockquote><blockquote><p>&quot;当年王重阳祖师在关中，十年练功，最后大周天通了。不是想着&#39;我要通大周天&#39;，是功夫到了自然通。&quot;</p></blockquote><blockquote><p>&quot;不要去追求大周天。百日功夫练好，小周天通了，再继续修，大周天自然会通。&quot;</p></blockquote><h2 id="了空居士的关键警告" tabindex="-1">了空居士的关键警告 <a class="header-anchor" href="#了空居士的关键警告" aria-label="Permalink to &quot;了空居士的关键警告&quot;">​</a></h2><p>了空居士特别强调：<strong>大周天不是追求来的，是功夫到了自然通的。</strong> 到处宣传&quot;我通了大小周天&quot;的人往往并不可信。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-小周天">小周天</a> — 大周天的基础</li><li><a href="/50-概念资料/dict-丹田">丹田</a> — 大小周天的能量核心</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-性命双修">性命双修</a> — 命功修炼</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>打好小周天基础</li><li>坚持每天静坐</li><li>不追求境界，境界自然会来</li></ul>',16)])])}const _=e(r,[["render",i]]);export{q as __pageData,_ as default};
